const now = Date.now();
function d(iso){ if(!iso) return null; const t=Date.parse(iso); return Number.isFinite(t) ? Math.floor((t-now)/86400000) : null; }
function d2(iso){ if(!iso) return 999; const t=Date.parse(iso); return Number.isFinite(t) ? Math.floor((now-t)/86400000) : 999; }
const out = [];
for (const it of items) {
  const p = it.json || {};
  const status = String(p.status || '').toLowerCase();
  if (!['new','in_progress','blocked'].includes(status)) continue;
  const daysToDeadline = d(p.deadline);
  const daysSinceUpdate = d2(p.updated_at);
  const flags = [];
  let risk = 'low';
  if (status === 'blocked') { flags.push('blocked'); risk = 'high'; }
  if (daysToDeadline !== null && daysToDeadline <= 3) { flags.push('deadline_imminent'); risk = 'critical'; }
  else if (daysToDeadline !== null && daysToDeadline <= 7) { flags.push('deadline_soon'); if(risk==='low') risk='high'; }
  if (daysSinceUpdate >= 7) { flags.push('stale'); if(risk==='low') risk='medium'; }
  if (daysSinceUpdate >= 14) { flags.push('very_stale'); if(risk!=='critical') risk='high'; }
  if (flags.length) {
    out.push({ json: { project: p, flags, risk, days_to_deadline: daysToDeadline, days_since_update: daysSinceUpdate } });
  }
}
return out;
